import{_ as a,o as l,c as i,a5 as n}from"./chunks/framework.CXroN2RO.js";const p=JSON.parse('{"title":"第17章 Unreal Engineのソースを読む","description":"","frontmatter":{"title":"第17章 Unreal Engineのソースを読む","study":{"source":"IT教本","status":"outline","summary":"UEのソースで追う入口を選び、一般的な仕組みとエンジン独自の実装を対応させる学習計画・概要です。参照するバージョンにより構成や名称が変わるため、手元のソースとデバッガで確かめながら読みます。\\n\\n## 関連する辞典本文・実践\\n\\n- [UObject・Actor・ActorComponent](","section":"learning","format":"path","domain":"game","collection":"low-level","order":18}},"headers":[],"relativePath":"guide/low-level/unreal-internals.md","filePath":"guide/low-level/unreal-internals.md"}'),t={name:"guide/low-level/unreal-internals.md"};function r(o,e,s,d,c,u){return l(),i("div",null,[...e[0]||(e[0]=[n(`<div id="第17章-unreal-engineの内部-──-ue5ソースコードリーディング" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="第17章-unreal-engineのソースを読む" tabindex="-1">第17章 Unreal Engineのソースを読む <a class="header-anchor" href="#第17章-unreal-engineのソースを読む" aria-label="Permalink to &quot;第17章 Unreal Engineのソースを読む&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>UEのソースで追う入口を選び、一般的な仕組みとエンジン独自の実装を対応させる<strong>学習計画・概要</strong>です。参照するバージョンにより構成や名称が変わるため、手元のソースとデバッガで確かめながら読みます。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponent</a>と<a href="/study/game/unreal/gc-and-object-pointers.html">GC・UPROPERTY</a>で、UE固有の型と寿命を調べられます。</li><li><a href="/study/game/unreal/build-system-ubt.html">UBT・Module・Build.cs</a>、<a href="/study/graphics/engine/unreal-renderer.html">Unrealのレンダラー</a>で、読む対象の構成を確認できます。</li></ul><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>UE5は<strong>ソースを参照できる大規模なゲームエンジン</strong>であり、このコースの知識を確かめる題材になる。 ここまでの16章はすべて「UE5を原文で読むための語彙」だったと言ってよい。 UObject/GC/リフレクション(第9章の拡張)、モジュールとDLL(第7章)、 TaskGraph(第8章)、RHI(第13章)、レンダースレッド(第8,11章)── UEの各機構を「一般原理の実装例」として読み解く。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>UE5のソースをビルドし、デバッガでエンジン内部にステップインできる</li><li>FEngineLoop::Tick()から始まる1フレームの流れをソース上で追える</li><li>UObject・リフレクション・GCの仕組みを説明できる</li><li>ゲームスレッド/レンダースレッド/RHIスレッドの分業を説明できる</li><li>Actor/Component/Tick/レプリケーション等の主要機構の実装位置を知っている</li><li>UnrealのタスクをC++で実装するとき、内部を意識した設計判断ができる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第7章(DLL・リンク)、第8章(スレッド)、第9章(C++・vtable)、 第13章(RHI相当の知識)、第15章(エンジン一般論)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>環境構築とコードの歩き方</strong><ul><li>GitHubからUE5取得→GenerateProjectFiles→VSでビルド(DebugGame Editor)</li><li>モジュール構造: Runtime/Core, CoreUObject, Engine, RHI, Renderer... 各モジュール=DLL(第7章の実物)。<code>*.Build.cs</code>と<code>MODULE_API</code></li><li>歩き方: シンボル検索(Ctrl+T)、参照検索、そして <strong>ブレークポイントとコールスタックで、実際の呼出し経路を確かめる</strong></li></ul></li><li><strong>Coreモジュール ── ここまでの教本の答え合わせ</strong><ul><li>TArray/TMap/FString(第9章自作コンテナの産業版)</li><li>FMemory/FMallocBinned2(第6章アロケータの産業版)</li><li>FRunnable/FTaskGraph/UE::Tasks(第8章ジョブシステムの産業版)</li><li>FPlatformMisc等のプラットフォーム抽象(第15章レイヤの実物)</li></ul></li><li><strong>UObjectシステム(UEの心臓)</strong><ul><li>UCLASS/UPROPERTY/UFUNCTIONマクロ → **UnrealHeaderTool(UHT)**が コード生成(*.generated.h)── 「C++にリフレクションを後付けする」手法</li><li>UClass(実行時型情報)、CDO(クラスデフォルトオブジェクト)</li><li><strong>ガベージコレクション</strong>: UPROPERTYが参照グラフを形成し マーク&amp;スイープ(第16章GCと比較せよ)。AddToRoot、TWeakObjectPtr</li><li>FName(文字列インターン)、FProperty(プロパティ反復)</li><li>シリアライズ(FArchive)とBlueprintがこの上に建つ構図</li></ul></li><li><strong>ゲームプレイフレームワーク</strong><ul><li>UWorld→ULevel→AActor→UActorComponent の所有構造</li><li>Tick系統(TickGroup、依存)、BeginPlay/EndPlayのライフサイクル</li><li>入力の旅(UEの中): FSlateApplication→PlayerController→ InputComponent(第14章の入力経路のUE版)</li><li>Blueprint VM(バイトコードインタプリタ! 第7章の知識で読める)と C++との呼び出し関係・コスト</li></ul></li><li><strong>レンダリングの3スレッド構造(UE理解の要)</strong><ul><li><strong>ゲームスレッド</strong>(UWorldを更新)→ プロキシ(FPrimitiveSceneProxy)を 介して → <strong>レンダースレッド</strong>(FSceneRendererがパスを構築)→ <strong>RHIスレッド</strong>(D3D12/Vulkanへコマンド変換)→ GPU</li><li>「ゲームスレッドはレンダーデータを直接触らない」規約と ENQUEUE_RENDER_COMMAND(第8章スレッド間通信の実物)</li><li>RDG(Render Dependency Graph)── レンダーグラフの産業実装</li><li>Nanite/Lumenは「存在と原理の概要」(GPU駆動描画・SDF/レイの融合) を知り、深掘りは発展編</li></ul></li><li><strong>ソースリーディング演習ルート(この章の本体)</strong><ul><li>ルートA: 起動 ── WinMain→GuardedMain→FEngineLoop::PreInit/Init/Tick</li><li>ルートB: 入力 ── XInput読み取り(WindowsApplication)→Slate→ PlayerController→あなたのBindAction</li><li>ルートC: Tick ── TickTaskManagerがTickGroupをTaskGraphに投げる様子</li><li>ルートD: 描画 ── AStaticMeshActorが画面に出るまで (プロキシ生成→可視性判定→BasePass→RHICmdList→D3D12)</li><li>ルートE: UObject ── NewObject→GUObjectArray登録→GC実行</li></ul></li><li><strong>UEでの実務に効く知識</strong><ul><li>モジュール追加・プラグイン構造、UBT/UATの役割</li><li>スタッツ(stat unit/stat game)、Unreal Insights(第18章へ)</li><li>よくあるクラッシュ(GC済みActorへのアクセス等)の内部的理由</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>UHTによるコード生成</strong> ── リフレクション・GC・BP・ネットワークの土台</li><li><strong>3スレッドパイプライン</strong> ── 1フレームの遅延と引き換えの並列性</li><li><strong>プロキシパターン</strong> ── スレッド間のデータ所有権分離</li><li><strong>「UEは一般原理の実装例」</strong> ── 暗記でなく対応付けで読む</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>UPROPERTYを付け忘れてActorが消える</td><td>GCの参照グラフ</td></tr><tr><td>BPが重い→C++化の判断</td><td>BP VMのコスト</td></tr><tr><td>ゲームスレッドからRTデータを触って稀にクラッシュ</td><td>3スレッド規約</td></tr><tr><td>stat unitのGame/Draw/GPUの意味</td><td>3スレッド+GPU計測</td></tr><tr><td>ビルド構成(DebugGame/Development)の使い分け</td><td>モジュール・最適化</td></tr><tr><td>エンジン改造(自社カスタムUE)</td><td>この章全部</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>UE5をソースビルドし、空プロジェクトを <strong>DebugGame Editor</strong> で起動、 <code>FEngineLoop::Tick</code> にブレークを張ってコールスタックを観察せよ。</li><li>ルートB(入力): パッドのAボタンに反応する自作ActorのC++ハンドラに ブレークを張り、コールスタックを<strong>上に</strong>辿って入力の発生源 (WindowsApplication/XInput)までノートに記録せよ。</li><li>ルートD(描画): RenderDocプラグインでUEのフレームをキャプチャし、 BasePass等をソース(FDeferredShadingSceneRenderer::Render)と 対応付けよ。</li><li><code>NewObject</code>で作ったUObjectをUPROPERTYなし参照で保持し、 GCで消される事故を意図的に起こし、原因をGCソースの動作で説明せよ。</li><li>最小のエンジン改造: FEngineLoop::Tickに自作ログ(フレーム番号と Δt)を仕込み、ビルドして動作確認せよ(「エンジンは編集できる ただのC++」という感覚を得る)。</li><li>stat unit で Game/Draw/GPU の数値を読み、自分のプロジェクトが どのスレッドバウンドか判定せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>『Unreal Engine 4で極めるゲーム開発』(historia)── UE和書の定番 (UE5でも思想は通用)</li><li>公式ドキュメント「Unreal Architecture」「Threaded Rendering」 「Actor Lifecycle」(一次情報として熟読)</li><li>『InsideUE4/UE5』系Web連載(知乎発の詳細解析の英訳・和訳記事群)</li><li>Michael Noland等のEpic技術ブログ</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>UnrealEngine 本体</strong>(EpicGames/UnrealEngine ── 要アカウント連携) この章の教材そのもの</li><li>Lyra Starter Game(公式サンプル。現代UEゲームプレイ設計の見本)</li><li>UnrealSharp等のバインディング系(UObjectリフレクションの応用例)</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>Inside Unreal(Epic公式)のエンジン解説回</li><li>&quot;Unreal Engine Game Framework: From int main() to BeginPlay&quot; (Alex Forsythe ── <strong>UE内部解説動画の最高傑作。必見</strong>)</li><li>&quot;Multithreading and Performance in Unreal&quot;(同氏)</li><li>UE Fest / CEDECのEpic Japan講演(おかず氏らのエンジン深掘り)</li></ul><h2 id="読むべきソースコード-読解ルートの再掲" tabindex="-1">読むべきソースコード(読解ルートの再掲) <a class="header-anchor" href="#読むべきソースコード-読解ルートの再掲" aria-label="Permalink to &quot;読むべきソースコード(読解ルートの再掲)&quot;">​</a></h2><ul><li><code>Launch/Private/LaunchEngineLoop.cpp</code>(FEngineLoop::Tick)</li><li><code>CoreUObject/Private/UObject/UObjectGlobals.cpp</code>(NewObject)、 <code>GarbageCollection.cpp</code></li><li><code>Engine/Private/Components/PrimitiveComponent.cpp</code> → <code>Renderer/Private/DeferredShadingRenderer.cpp</code></li><li><code>Core/Private/HAL/MallocBinned2.cpp</code>(第6章の答え合わせ)</li><li><code>TickTaskManager.cpp</code>(第8章の答え合わせ)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>UPROPERTYマクロは最終的に何を生成し、GCとどう関係するか。</li><li>CDOとは何か。SpawnActorのコストとの関係は?</li><li>ゲームスレッドとレンダースレッドはどうデータを受け渡すか。 なぜ直接共有しないのか(第8章の言葉で)。</li><li>stat unitでGame 20ms / Draw 8ms / GPU 10ms のとき何を最適化すべきか。</li><li>BlueprintはどうやってC++関数を呼ぶか(リフレクションの言葉で)。</li><li>「Actorへの生ポインタをメンバに持つと危険」な理由をGCの仕組みから。</li><li>FEngineLoop::Tickの中で行われる主要な仕事を5つ挙げよ。</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>UE5製ゲームの1フレーム(3スレッド並走)</span></span>
<span class="line"><span>──────────────────────────────────────────────────────</span></span>
<span class="line"><span>GameThread   : 入力→PlayerController→Actor Tick群(TaskGraph並列)</span></span>
<span class="line"><span>               →プロキシ更新をRTへEnqueue ─┐</span></span>
<span class="line"><span>RenderThread : (1フレーム遅れ)可視性判定→RDGでパス構築→ ─┐</span></span>
<span class="line"><span>RHIThread    : RHICmdListをD3D12コマンドへ変換→Submit ──→ GPU</span></span>
<span class="line"><span>──────────────────────────────────────────────────────</span></span>
<span class="line"><span>裏方: UObject GC(ヒッチの原因にも) / FMallocBinned2(全確保)</span></span>
<span class="line"><span>      UHT生成コード(BP・ネット・エディタ連携の土台)</span></span>
<span class="line"><span>= 第8章(スレッド)+第13章(API)+第15章(エンジン)の最大実装例</span></span></code></pre></div>`,33)])])}const g=a(t,[["render",r]]);export{p as __pageData,g as default};
